// Flatten a Telegram update (message or button press) into one shape.
const update = $input.first().json;
const out = { update_id: update.update_id ?? null };

if (update.callback_query) {
  const cq = update.callback_query;
  out.kind = 'callback';
  out.chat_id = cq.message?.chat?.id ?? cq.from?.id ?? null;
  out.from_id = cq.from?.id ?? null;
  out.callback_id = cq.id;
  out.callback_data = cq.data ?? '';
  out.message_id = cq.message?.message_id ?? null;
  out.text = '';
  out.photo_file_id = null;
} else {
  const m = update.message ?? {};
  const photos = m.photo ?? [];
  out.chat_id = m.chat?.id ?? null;
  out.from_id = m.from?.id ?? null;
  out.message_id = m.message_id ?? null;
  // Telegram sends several sizes; the last one is the largest.
  out.photo_file_id = photos.length ? photos[photos.length - 1].file_id : null;
  out.text = String(m.text ?? m.caption ?? '').trim();
  if (out.photo_file_id) out.kind = 'photo';
  else if (out.text.startsWith('/')) out.kind = 'command';
  else if (out.text) out.kind = 'text';
  else out.kind = 'unsupported';
}

// Updates without a chat (e.g. edited messages we did not subscribe to) are dropped.
if (!out.chat_id) return [];
return [{ json: out }];

// Merge the update with the client lookup and decide which branch handles it.
const update = $('Normalize Update').first().json;
const client = $input.first().json;

const ROUTES = [
  'unauthorized', 'help', 'new_post', 'callback', 'edit_feedback',
  'schedule_time', 'cancel', 'link_chat', 'login_link',
];

const ctx = {
  ...update,
  client_id: client.client_id ?? null,
  client_name: client.client_name ?? null,
  is_admin: client.is_admin === true,
  timezone: client.timezone ?? 'UTC',
  session_mode: client.session_mode ?? null,
  session_post_id: client.session_post_id ?? null,
};

let cmd = null;
let arg = '';
if (update.kind === 'command') {
  cmd = update.text.split(/\s+/)[0].split('@')[0].toLowerCase();
  arg = update.text.replace(/^\/\S+\s*/, '').trim();
}

let route;
if (cmd === '/start' && arg.startsWith('link_')) {
  // Deep link from the dashboard signup page: t.me/<bot>?start=link_<code>
  ctx.link_code = arg.slice('link_'.length);
  route = 'link_chat';
} else if (cmd === '/dashboard' || cmd === '/login' || (cmd === '/start' && arg === 'login')) {
  route = ctx.client_id || ctx.is_admin ? 'login_link' : 'unauthorized';
} else if (!ctx.client_id) {
  route = 'unauthorized';
} else if (update.kind === 'callback') {
  route = 'callback';
} else if (cmd) {
  if (cmd === '/cancel') route = 'cancel';
  else if ((cmd === '/new' || cmd === '/post') && arg) {
    ctx.text = arg;
    route = 'new_post';
  } else route = 'help';
} else if (update.kind === 'text' && ctx.session_mode === 'awaiting_edit') {
  route = 'edit_feedback';
} else if (update.kind === 'text' && ctx.session_mode === 'awaiting_schedule') {
  route = 'schedule_time';
} else if (update.kind === 'photo' || update.kind === 'text') {
  route = 'new_post';
} else {
  route = 'help';
}

ctx.route = route;
ctx.route_index = ROUTES.indexOf(route);
return [{ json: ctx }];

// Object-storage key for the client's photo. Telegram re-encodes photos as JPEG.
const ctx = $input.first().json;
const media_key = `posts/${ctx.client_id}/${Date.now()}-${ctx.message_id}.jpg`;
return [{ json: { ...ctx, media_key } }];

// Button payloads look like "p:<action>:<post uuid>".
const ctx = $('Build Context').first().json;
const [prefix, action, postId] = String(ctx.callback_data).split(':');
const valid = prefix === 'p' && /^[0-9a-f-]{36}$/i.test(postId ?? '');

return [{
  json: {
    ...ctx,
    action: valid ? action : 'invalid',
    // Placeholder keeps the ::uuid cast in the next query from failing.
    post_id: valid ? postId : '00000000-0000-0000-0000-000000000000',
  },
}];

// Only allow a button if the post is still in a state where it makes sense.
const ctx = $('Parse Callback').first().json;
const post = $input.first().json;

const ACTIONS = ['pub', 'sch', 'edt', 'rgn', 'rej', 'rty', 'stale'];
const ALLOWED_FROM = {
  pub: ['pending_approval', 'scheduled'],
  sch: ['pending_approval', 'scheduled'],
  edt: ['pending_approval'],
  rgn: ['pending_approval'],
  rej: ['pending_approval', 'scheduled'],
  rty: ['failed', 'partially_published'],
};

let action = ctx.action;
if (!post.post_id || !ALLOWED_FROM[action]?.includes(post.status)) action = 'stale';

return [{
  json: {
    ...ctx,
    post_status: post.status ?? 'missing',
    action,
    action_index: ACTIONS.indexOf(action),
  },
}];

